# Hand-written, not generated by dist: vix-zgui has no release binaries, so
# this compiles the crates.io crate. See gui/vix-zgui/spec/index.md in
# vixide/vix ("Distribution"). Bump url and sha256 with each publish.
class VixZgui < Formula
  desc "Vix desktop GUI on zgui (reactive, CSS-styled, wgpu-drawn)"
  homepage "https://github.com/vixide/vix"
  url "https://static.crates.io/crates/vix-zgui/vix-zgui-2.0.2.crate"
  sha256 "32b5b854192ba355ab5da8db50e8691526d8d1dbc8b0c74bd75356b4f2cc7c84"
  license any_of: ["Apache-2.0", "BSD-3-Clause", "MIT", "GPL-3.0-only"]

  depends_on "rust" => :build

  on_linux do
    depends_on "pkgconf" => :build
    depends_on "fontconfig"
    depends_on "libxkbcommon"
    depends_on "wayland"
  end

  def install
    system "cargo", "install", *std_cargo_args
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/vix-zgui --version")
  end
end
